  "logic": "class Component extends DCLogic {\n  pillar() {\n    const PILLARS = {\n      productie: { bg: \"#FC06E5\", dark: \"#7B1FA2\", title: \"#060228\", label: \"Productie\" },\n      jump:      { bg: \"#49FF9F\", dark: \"#2F7E4D\", title: \"#060228\", label: \"JUMP\" },\n      marketing: { bg: \"#FFCC00\", dark: \"#C25100\", title: \"#060228\", label: \"Marketing\" },\n      content:   { bg: \"#00FFE6\", dark: \"#008B8B\", title: \"#060228\", label: \"Content\" },\n      standaard: { bg: \"#3D5AFE\", dark: \"#060228\", title: \"#ffffff\", label: \"ByTomorrow\" },\n      navy:      { bg: \"#060228\", dark: \"#3D5AFE\", title: \"#ffffff\", label: \"ByTomorrow\" },\n    };\n    return PILLARS[this.props.pillar] || PILLARS.productie;\n  }\n  applyVars() {\n    const p = this.pillar(), r = window.__bytRoot.style;\n    r.setProperty(\"--bg\", p.bg);\n    r.setProperty(\"--title\", p.title);\n    r.setProperty(\"--pill-bg\", p.dark);\n    r.setProperty(\"--pill-text\", \"#ffffff\");\n  }\n  componentDidMount() { this.applyVars(); }\n  componentDidUpdate() { this.applyVars(); }\n  renderVals() {\n    const p = this.pillar();\n    const SPORTS = {\n      basketbal: \"sports_basketball\",\n      volleybal: \"sports_volleyball\",\n      handbal: \"sports_handball\",\n      voetbal: \"sports_soccer\",\n      tennis: \"sports_tennis\",\n      padel: \"sports_tennis\",\n      hockey: \"sports_hockey\",\n      zwemmen: \"pool\",\n      hardlopen: \"directions_run\",\n      wielrennen: \"directions_bike\",\n      turnen: \"sports_gymnastics\",\n      vechtsport: \"sports_martial_arts\",\n      honkbal: \"sports_baseball\",\n      rugby: \"sports_rugby\",\n      golf: \"sports_golf\",\n      schaatsen: \"ice_skating\",\n      skien: \"downhill_skiing\",\n      fitness: \"fitness_center\",\n      roeien: \"rowing\",\n      zeilen: \"sailing\",\n      esports: \"sports_esports\",\n      finish: \"sports_score\",\n    };\n    const line2 = this.props.titleLine2 ?? \"Bulgarije\";\n    return {\n      pillar_label: this.props.pillarLabel || p.label,\n      competition: this.props.competition ?? \"NBB\",\n      datetime: this.props.datetime ?? \"20-08 | 19:30\",\n      titleLine1: this.props.titleLine1 ?? \"Orange Lions\",\n      titleLine2: line2,\n      hasLine2: !!(line2 && String(line2).trim()),\n      platform: this.props.platform ?? \"HBO max\",\n      sportIcon: SPORTS[this.props.sport] || \"sports_basketball\",\n    };\n  }\n}",
